2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName", expression = "java(formatDisplayName(owner))")
22	    @Mapping(target = "initials", expression = "java(formatInitials(owner))")
23	    OwnerDto toOwnerDto(Owner owner);
24	
25	    /**
26	     * Formats an owner's stored names as {@code "LastName, FirstName"} for display.
27	     */
28	    default String formatDisplayName(Owner owner) {
29	        if (owner == null) {
30	            return null;
31	        }
32	        return owner.getLastName() + ", " + owner.getFirstName();
33	    }
34	
35	    /**
36	     * Builds an owner's initials as the upper-cased first letters of the first and last
37	     * name, dot-separated with a trailing dot (e.g. {@code "J.S."}).
38	     */
39	    default String formatInitials(Owner owner) {
40	        if (owner == null) {
41	            return null;
42	        }
43	        return initial(owner.getFirstName()) + initial(owner.getLastName());
44	    }
45	
46	    private String initial(String name) {
47	        return Character.toUpperCase(name.charAt(0)) + ".";
48	    }
49	
50	    Owner toOwner(OwnerDto ownerDto);
51	
52	    @Mapping(target = "id", ignore = true)
53	    @Mapping(target = "pets", ignore = true)
54	    Owner toOwner(OwnerFieldsDto ownerDto);
55	
56	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
57	
58	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
59	
60	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
61	        OwnerPageDto ownerPageDto = new OwnerPageDto();
62	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
63	        ownerPageDto.setPage(ownerPage.getNumber());
64	        ownerPageDto.setSize(ownerPage.getSize());
65	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
66	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
67	        return ownerPageDto;
68	    }
69	}
