50	
51	import jakarta.transaction.Transactional;
52	
53	/**
54	 * @author Vitaliy Fedoriv
55	 */
56	
57	@RestController
58	@CrossOrigin(exposedHeaders = "errors, content-type")
59	@RequestMapping("/api")
60	public class OwnerRestControllerV1 implements OwnersApi {
61	
62	    private final ClinicService clinicService;
63	
64	    private final OwnerMapper ownerMapper;
65	
66	    private final PetMapper petMapper;
67	
68	    private final VisitMapper visitMapper;
69	
70	    private final OwnerFieldsValidator ownerFieldsValidator;
71	
72	    private final TelephoneNormalizer telephoneNormalizer;
73	
74	    private final EmailNormalizer emailNormalizer;
75	
76	    public OwnerRestControllerV1(ClinicService clinicService,
77	                                 OwnerMapper ownerMapper,
78	                                 PetMapper petMapper,
79	                                 VisitMapper visitMapper,
80	                                 OwnerFieldsValidator ownerFieldsValidator,
81	                                 TelephoneNormalizer telephoneNormalizer,
82	                                 EmailNormalizer emailNormalizer) {
83	        this.clinicService = clinicService;
84	        this.ownerMapper = ownerMapper;
85	        this.petMapper = petMapper;
86	        this.visitMapper = visitMapper;
87	        this.ownerFieldsValidator = ownerFieldsValidator;
88	        this.telephoneNormalizer = telephoneNormalizer;
89	        this.emailNormalizer = emailNormalizer;
90	    }
91	
92	    /**
93	     * Registers the {@link OwnerFieldsValidator} so incoming owner payloads are checked for
94	     * missing or blank mandatory fields as part of the standard {@code @Valid} pass.
95	     */
96	    @InitBinder("ownerFieldsDto")
97	    void initOwnerFieldsBinder(WebDataBinder binder) {
98	        binder.addValidators(ownerFieldsValidator);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
104	        Collection<Owner> owners;
105	        if (lastName != null) {
106	            owners = this.clinicService.findOwnerByLastName(lastName);
107	        } else {
108	            owners = this.clinicService.findAllOwners();
109	        }
110	        if (owners.isEmpty()) {
111	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
112	        }
113	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
119	        Owner owner = this.clinicService.findOwnerById(ownerId);
120	        if (owner == null) {
121	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
122	        }
123	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
124	    }
125	
126	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
127	    @Override
128	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
129	        HttpHeaders headers = new HttpHeaders();
130	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
131	        String telephone = telephoneNormalizer.normalize(owner.getTelephone());
132	        if (!this.clinicService.findOwnerByTelephone(telephone).isEmpty()) {
133	            throw new DuplicateTelephoneException(telephone);
134	        }
135	        owner.setTelephone(telephone);
136	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
137	        this.clinicService.saveOwner(owner);
138	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
139	        headers.setLocation(UriComponentsBuilder.newInstance()
140	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
141	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
142	    }
143	
144	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
145	    @Override
146	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
147	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
148	        if (currentOwner == null) {
149	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
150	        }
151	        currentOwner.setAddress(ownerFieldsDto.getAddress());
152	        currentOwner.setCity(ownerFieldsDto.getCity());
153	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
154	        currentOwner.setLastName(ownerFieldsDto.getLastName());
155	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
156	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
157	        this.clinicService.saveOwner(currentOwner);
158	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
159	    }
160	
161	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
162	    @Transactional
163	    @Override
164	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
165	        Owner owner = this.clinicService.findOwnerById(ownerId);
166	        if (owner == null) {
167	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
168	        }
169	        this.clinicService.deleteOwner(owner);
170	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
171	    }
172	
173	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
174	    @Override
175	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
176	        Owner owner = this.clinicService.findOwnerById(ownerId);
177	        if (owner == null) {
178	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
179	        }
180	        HttpHeaders headers = new HttpHeaders();
181	        Pet pet = petMapper.toPet(petFieldsDto);
182	        owner.setId(ownerId);
183	        pet.setOwner(owner);
184	        pet.getType().setName(null);
185	        this.clinicService.savePet(pet);
186	        PetDto petDto = petMapper.toPetDto(pet);
187	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
188	            .buildAndExpand(pet.getId()).toUri());
189	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
190	    }
191	
192	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
193	    @Override
194	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
195	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
196	        if (currentOwner != null) {
197	            Pet currentPet = this.clinicService.findPetById(petId);
198	            if (currentPet != null) {
199	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
200	                currentPet.setName(petFieldsDto.getName());
201	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
202	                this.clinicService.savePet(currentPet);
203	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
204	            }
205	        }
206	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
207	    }
208	
209	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
210	    @Override
211	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
212	        HttpHeaders headers = new HttpHeaders();
213	        Visit visit = visitMapper.toVisit(visitFieldsDto);
214	        Pet pet = new Pet();
215	        pet.setId(petId);
216	        visit.setPet(pet);
217	        this.clinicService.saveVisit(visit);
218	        VisitDto visitDto = visitMapper.toVisitDto(visit);
219	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
220	            .buildAndExpand(visit.getId()).toUri());
221	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
222	    }
223	
224	
225	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
226	    @Override
227	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
228	        Owner owner = this.clinicService.findOwnerById(ownerId);
229	        if (owner != null) {
230	            Pet pet = owner.getPet(petId);
231	            if (pet != null) {
232	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
233	            }
234	        }
235	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
236	    }
237	}
